/**
 * @file      test_main.cpp
 * @brief     Unit tests for hal/link/link_frame.{h,cpp} against the golden vectors.
 *
 * The JSON vectors under protocol/vectors/ are generated by
 * protocol/tools/mkvectors.py (the reference implementation) and turned into
 * link_vectors_gen.h by support/gen_link_vectors.py at build time. These tests
 * replay every vector through the firmware codec: message encode/decode,
 * segmentation, reassembly (including the discard-state faults) and the bulk
 * DATA / ACK payloads.
 */
#include "link_vectors_gen.h"

#include <unity.h>

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

#include "hal/link/link_frame.h"
#include "hal/link/link_xfer.h"

using namespace pagerlink;

void setUp(void) {}
void tearDown(void) {}

static int hex_nibble(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

/* Decode a lowercase-hex C string into raw bytes. */
static std::string hex_to_bytes(const char *hex)
{
    std::string out;
    const size_t n = std::strlen(hex);
    out.reserve(n / 2);
    for (size_t i = 0; i + 1 < n; i += 2) {
        const int hi = hex_nibble(hex[i]);
        const int lo = hex_nibble(hex[i + 1]);
        out.push_back(static_cast<char>((hi << 4) | lo));
    }
    return out;
}

/* Encode raw bytes as lowercase hex. */
static std::string bytes_to_hex(const std::string &b)
{
    static const char *digits = "0123456789abcdef";
    std::string out;
    out.reserve(b.size() * 2);
    for (unsigned char c : b) {
        out.push_back(digits[c >> 4]);
        out.push_back(digits[c & 0x0F]);
    }
    return out;
}

static void test_message_valid_roundtrip(void)
{
    for (size_t i = 0; i < kMsgValidCount; ++i) {
        const VecMsgValid &v = kMsgValid[i];
        const std::string bytes = hex_to_bytes(v.bytes_hex);

        Message m{};
        const DecodeError err =
            decode_message(reinterpret_cast<const uint8_t *>(bytes.data()), bytes.size(), m);
        TEST_ASSERT_EQUAL_MESSAGE((int)DecodeError::None, (int)err, v.name);
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(v.type, (uint8_t)m.type, v.name);
        TEST_ASSERT_EQUAL_UINT16_MESSAGE(v.id, m.id, v.name);
        const std::string payload_hex = bytes_to_hex(m.payload);
        TEST_ASSERT_EQUAL_STRING_MESSAGE(v.payload_hex, payload_hex.c_str(), v.name);

        const std::string payload = hex_to_bytes(v.payload_hex);
        std::string out;
        const bool ok = encode_message(m.type, m.id,
                                       reinterpret_cast<const uint8_t *>(payload.data()),
                                       payload.size(), out);
        TEST_ASSERT_TRUE_MESSAGE(ok, v.name);
        const std::string out_hex = bytes_to_hex(out);
        TEST_ASSERT_EQUAL_STRING_MESSAGE(v.bytes_hex, out_hex.c_str(), v.name);
    }
}

static void test_message_malformed_reasons(void)
{
    for (size_t i = 0; i < kMsgBadCount; ++i) {
        const VecMsgBad &v = kMsgBad[i];
        const std::string bytes = hex_to_bytes(v.bytes_hex);
        Message m{};
        const DecodeError err =
            decode_message(reinterpret_cast<const uint8_t *>(bytes.data()), bytes.size(), m);
        TEST_ASSERT_EQUAL_STRING_MESSAGE(v.reason, decode_error_name(err), v.name);
    }
}

static void test_segment_packets(void)
{
    for (size_t i = 0; i < kSegmentCount; ++i) {
        const VecSegment &v = kSegment[i];
        const std::string msg = hex_to_bytes(v.message_hex);

        Segmenter seg;
        seg.set_seq(v.start_seq);
        std::vector<std::string> got;
        const bool ok = seg.send(
            reinterpret_cast<const uint8_t *>(msg.data()), msg.size(), v.packet_size,
            [&](const uint8_t *pkt, size_t len) {
                got.push_back(std::string(reinterpret_cast<const char *>(pkt), len));
                return true;
            });
        TEST_ASSERT_TRUE_MESSAGE(ok, v.name);
        TEST_ASSERT_EQUAL_UINT_MESSAGE((size_t)v.n_packets, got.size(), v.name);
        for (size_t j = 0; j < got.size(); ++j) {
            const std::string hex = bytes_to_hex(got[j]);
            TEST_ASSERT_EQUAL_STRING_MESSAGE(v.packets[j], hex.c_str(), v.name);
        }
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(v.next_seq, seg.seq(), v.name);
    }
}

static void test_segment_reassembles(void)
{
    for (size_t i = 0; i < kSegmentCount; ++i) {
        const VecSegment &v = kSegment[i];
        /* A non-zero start_seq cannot be reproduced from a fresh (seq 0) receiver. */
        if (v.start_seq != 0) {
            continue;
        }
        std::string got;
        bool have = false;
        Reassembler r(
            [&](const uint8_t *m, size_t n) {
                got.assign(reinterpret_cast<const char *>(m), n);
                have = true;
            },
            [](ResetReason) {});
        for (size_t j = 0; j < v.n_packets; ++j) {
            const std::string pkt = hex_to_bytes(v.packets[j]);
            r.feed(reinterpret_cast<const uint8_t *>(pkt.data()), pkt.size());
        }
        TEST_ASSERT_TRUE_MESSAGE(have, v.name);
        const std::string got_hex = bytes_to_hex(got);
        TEST_ASSERT_EQUAL_STRING_MESSAGE(v.message_hex, got_hex.c_str(), v.name);
    }
}

static void test_reassemble_events(void)
{
    for (size_t i = 0; i < kReassembleCount; ++i) {
        const VecReassemble &v = kReassemble[i];
        std::vector<std::string> got;
        Reassembler r(
            [&](const uint8_t *m, size_t n) {
                got.push_back("m:" + bytes_to_hex(std::string(reinterpret_cast<const char *>(m), n)));
            },
            [&](ResetReason rr) { got.push_back(std::string("r:") + reset_reason_name(rr)); });
        for (size_t j = 0; j < v.n_packets; ++j) {
            const std::string pkt = hex_to_bytes(v.packets[j]);
            r.feed(reinterpret_cast<const uint8_t *>(pkt.data()), pkt.size());
        }
        TEST_ASSERT_EQUAL_UINT_MESSAGE((size_t)v.n_events, got.size(), v.name);
        for (size_t j = 0; j < v.n_events; ++j) {
            const VecEvent &e = v.events[j];
            const std::string want = (e.kind == 'm' ? "m:" : "r:") + std::string(e.text);
            TEST_ASSERT_EQUAL_STRING_MESSAGE(want.c_str(), got[j].c_str(), v.name);
        }
    }
}

static void test_bulk_data_roundtrip(void)
{
    for (size_t i = 0; i < kDataCount; ++i) {
        const VecData &v = kData[i];
        const std::string bytes = hex_to_bytes(v.bytes_hex);

        std::string out;
        const bool ok = encode_data(v.offset, reinterpret_cast<const uint8_t *>(bytes.data()),
                                    bytes.size(), out);
        TEST_ASSERT_TRUE_MESSAGE(ok, "kData");
        const std::string out_hex = bytes_to_hex(out);
        TEST_ASSERT_EQUAL_STRING_MESSAGE(v.payload_hex, out_hex.c_str(), "kData");

        uint32_t offset = 0;
        const uint8_t *decoded = nullptr;
        size_t n = 0;
        const bool ok2 = decode_data(reinterpret_cast<const uint8_t *>(out.data()), out.size(),
                                     offset, decoded, n);
        TEST_ASSERT_TRUE_MESSAGE(ok2, "kData");
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(v.offset, offset, "kData");
        TEST_ASSERT_EQUAL_UINT_MESSAGE(bytes.size(), n, "kData");
        const std::string decoded_hex =
            bytes_to_hex(std::string(reinterpret_cast<const char *>(decoded), n));
        TEST_ASSERT_EQUAL_STRING_MESSAGE(v.bytes_hex, decoded_hex.c_str(), "kData");
    }
}

static void test_bulk_ack_roundtrip(void)
{
    for (size_t i = 0; i < kAckCount; ++i) {
        const VecAck &v = kAck[i];
        std::string out;
        encode_ack(v.next, v.credits, out);
        const std::string out_hex = bytes_to_hex(out);
        TEST_ASSERT_EQUAL_STRING_MESSAGE(v.payload_hex, out_hex.c_str(), "kAck");

        uint32_t next = 0;
        uint16_t credits = 0;
        const bool ok = decode_ack(reinterpret_cast<const uint8_t *>(out.data()), out.size(), next,
                                   credits);
        TEST_ASSERT_TRUE_MESSAGE(ok, "kAck");
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(v.next, next, "kAck");
        TEST_ASSERT_EQUAL_UINT16_MESSAGE(v.credits, credits, "kAck");
    }
}

static void test_bulk_bad_rejected(void)
{
    for (size_t i = 0; i < kBadDataCount; ++i) {
        const VecBad &v = kBadData[i];
        const std::string payload = hex_to_bytes(v.payload_hex);
        uint32_t offset = 0;
        const uint8_t *bytes = nullptr;
        size_t n = 0;
        const bool ok = decode_data(reinterpret_cast<const uint8_t *>(payload.data()),
                                    payload.size(), offset, bytes, n);
        TEST_ASSERT_FALSE_MESSAGE(ok, v.name);
    }
    for (size_t i = 0; i < kBadAckCount; ++i) {
        const VecBad &v = kBadAck[i];
        const std::string payload = hex_to_bytes(v.payload_hex);
        uint32_t next = 0;
        uint16_t credits = 0;
        const bool ok = decode_ack(reinterpret_cast<const uint8_t *>(payload.data()),
                                   payload.size(), next, credits);
        TEST_ASSERT_FALSE_MESSAGE(ok, v.name);
    }
}

static void test_crc32_vectors(void)
{
    for (size_t i = 0; i < kCrc32Count; ++i) {
        const VecCrc32 &v = kCrc32[i];
        const std::string bytes = hex_to_bytes(v.input_hex);
        const uint8_t *data = reinterpret_cast<const uint8_t *>(bytes.data());
        const size_t n = bytes.size();

        TEST_ASSERT_EQUAL_UINT32_MESSAGE(v.crc32, crc32_update(0, data, n), v.name);

        /* Incremental use must match the one-shot value, byte-split anywhere. */
        const size_t half = n / 2;
        uint32_t part = crc32_update(0, data, half);
        part = crc32_update(part, data + half, n - half);
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(v.crc32, part, v.name);
    }
}

static void test_segmenter_send_rejects_bad_args(void)
{
    Segmenter seg;
    const uint8_t msg[4] = {1, 2, 3, 4};
    auto sink = [](const uint8_t *, size_t) { return true; };
    TEST_ASSERT_FALSE(seg.send(msg, sizeof(msg), 1, sink)); /* packet_size < 2 */
    TEST_ASSERT_FALSE(seg.send(msg, 0, 20, sink));          /* len == 0 */
    TEST_ASSERT_EQUAL_UINT8(0, seg.seq());
}

static void test_segmenter_send_sink_abort(void)
{
    Segmenter seg;
    seg.set_seq(0);
    uint8_t msg[64];
    for (size_t i = 0; i < sizeof(msg); ++i) {
        msg[i] = static_cast<uint8_t>(i);
    }
    int calls = 0;
    const bool ok = seg.send(msg, sizeof(msg), 20, [&](const uint8_t *, size_t) {
        ++calls;
        return calls < 2;
    });
    TEST_ASSERT_FALSE(ok);
    TEST_ASSERT_EQUAL_INT(2, calls);       /* second packet was offered and rejected */
    TEST_ASSERT_EQUAL_UINT8(1, seg.seq()); /* seq advanced only for the accepted packet */
}

static void test_rx_window(void)
{
    /* 4102 = MAX_MESSAGE; 244/20 are the TCP/BLE and minimum packet sizes. */
    TEST_ASSERT_EQUAL_UINT(17, (unsigned)packets_per_message(4102, 244));
    TEST_ASSERT_EQUAL_UINT(216, (unsigned)packets_per_message(4102, 20));
    TEST_ASSERT_EQUAL_UINT(0, (unsigned)packets_per_message(0, 244));
    TEST_ASSERT_EQUAL_UINT(0, (unsigned)packets_per_message(10, 1));

    TEST_ASSERT_EQUAL_UINT16(16, rx_credits_for(0, 244));    /* unbounded */
    TEST_ASSERT_EQUAL_UINT16(16, rx_credits_for(272, 244));  /* 16 messages, capped */
    TEST_ASSERT_EQUAL_UINT16(16, rx_credits_for(1000, 244)); /* more than a window */
    TEST_ASSERT_EQUAL_UINT16(2, rx_credits_for(34, 244));
    TEST_ASSERT_EQUAL_UINT16(1, rx_credits_for(16, 244)); /* less than one message */
    TEST_ASSERT_EQUAL_UINT16(1, rx_credits_for(272, 20));
    TEST_ASSERT_EQUAL_UINT16(1, rx_credits_for(100, 1)); /* bad packet size */

    TEST_ASSERT_EQUAL_UINT(4, rx_ack_every_for(16));
    TEST_ASSERT_EQUAL_UINT(4, rx_ack_every_for(8));
    TEST_ASSERT_EQUAL_UINT(2, rx_ack_every_for(7));
    TEST_ASSERT_EQUAL_UINT(2, rx_ack_every_for(4));
    TEST_ASSERT_EQUAL_UINT(1, rx_ack_every_for(3));
    TEST_ASSERT_EQUAL_UINT(1, rx_ack_every_for(1));
}

static void test_packet_size_for_mtu(void)
{
    /* MTU clamped to 23..max_mtu, then minus the 3-byte ATT header. */
    TEST_ASSERT_EQUAL_UINT(244, (unsigned)packet_size_for_mtu(247, 247));
    TEST_ASSERT_EQUAL_UINT(244, (unsigned)packet_size_for_mtu(517, 247)); /* clamped to max */
    TEST_ASSERT_EQUAL_UINT(20, (unsigned)packet_size_for_mtu(23, 247));   /* BLE minimum */
    TEST_ASSERT_EQUAL_UINT(20, (unsigned)packet_size_for_mtu(0, 247));    /* raised to 23 */
    TEST_ASSERT_EQUAL_UINT(182, (unsigned)packet_size_for_mtu(185, 247));
    TEST_ASSERT_EQUAL_UINT(47, (unsigned)packet_size_for_mtu(100, 50)); /* lowered to max */
}

static void test_next_conn_band(void)
{
    /* Any activity keeps the link in the transfer band. */
    TEST_ASSERT_TRUE(next_conn_band(pagerlink::ConnBand::Idle, true, 0, 0) ==
                     pagerlink::ConnBand::Transfer);
    TEST_ASSERT_TRUE(next_conn_band(pagerlink::ConnBand::Transfer, true, 5000, 1000) ==
                     pagerlink::ConnBand::Transfer);

    /* Transfer survives until BULK_IDLE_MS without activity, then falls back. */
    TEST_ASSERT_TRUE(next_conn_band(pagerlink::ConnBand::Transfer, false, 1000 + 1999, 1000) ==
                     pagerlink::ConnBand::Transfer);
    TEST_ASSERT_TRUE(next_conn_band(pagerlink::ConnBand::Transfer, false, 3000, 1000) ==
                     pagerlink::ConnBand::Idle);
    TEST_ASSERT_TRUE(next_conn_band(pagerlink::ConnBand::Idle, false, 100000, 0) ==
                     pagerlink::ConnBand::Idle);

    /* The elapsed-time subtraction must wrap safely. */
    TEST_ASSERT_TRUE(next_conn_band(pagerlink::ConnBand::Transfer, false, 0x00000400, 0xFFFFFC00) ==
                     pagerlink::ConnBand::Idle); /* 2048 ms */
    TEST_ASSERT_TRUE(next_conn_band(pagerlink::ConnBand::Transfer, false, 0x00000100, 0xFFFFFC00) ==
                     pagerlink::ConnBand::Transfer); /* 1280 ms */
}

static void test_min_wait_ms(void)
{
    /* A future deadline shortens the wait, but never below `best`. */
    TEST_ASSERT_EQUAL_UINT32(2000, min_wait_ms(10000, 1000, 3000));
    TEST_ASSERT_EQUAL_UINT32(500, min_wait_ms(500, 1000, 3000));

    /* A deadline at or behind now contributes nothing. */
    TEST_ASSERT_EQUAL_UINT32(0, min_wait_ms(10000, 1000, 1000));
    TEST_ASSERT_EQUAL_UINT32(0, min_wait_ms(10000, 5000, 1000));

    /* Folding several deadlines keeps the nearest future one. */
    uint32_t w = 10000;
    w = min_wait_ms(w, 100, 2100);
    w = min_wait_ms(w, 100, 900);
    w = min_wait_ms(w, 100, 30100);
    TEST_ASSERT_EQUAL_UINT32(800, w);

    /* The deadline subtraction must wrap safely. */
    TEST_ASSERT_EQUAL_UINT32(512, min_wait_ms(10000, 0xFFFFFF00, 0x00000100));
    TEST_ASSERT_EQUAL_UINT32(0, min_wait_ms(10000, 0x00000100, 0xFFFFFF00));
}

/* ------------------------------------------------ zero-copy codec paths */

static void test_decode_view_matches_copy(void)
{
    std::string bytes;
    TEST_ASSERT_TRUE(encode_message(MsgType::Res, 7,
                                    reinterpret_cast<const uint8_t *>("hello"), 5, bytes));

    MessageView v;
    TEST_ASSERT_EQUAL((int)DecodeError::None,
                      (int)decode_message_view(reinterpret_cast<const uint8_t *>(bytes.data()),
                                               bytes.size(), v));
    TEST_ASSERT_EQUAL_UINT8((uint8_t)MsgType::Res, (uint8_t)v.type);
    TEST_ASSERT_EQUAL_UINT16(7, v.id);
    TEST_ASSERT_EQUAL_UINT(5, (unsigned)v.len);
    TEST_ASSERT_TRUE(v.payload ==
                     reinterpret_cast<const uint8_t *>(bytes.data()) + HEADER_SIZE);
    TEST_ASSERT_EQUAL_INT(0, std::memcmp(v.payload, "hello", 5));

    static const uint8_t b_short[] = {1, 1, 0, 0, 0};
    static const uint8_t b_version[] = {2, 1, 0, 0, 0, 0};
    static const uint8_t b_type[] = {1, 6, 0, 0, 0, 0};
    static const uint8_t b_oversize[] = {1, 1, 0, 0, 0x01, 0x10}; /* len 4097 */
    static const uint8_t b_length[] = {1, 1, 0, 0, 3, 0, 'a'};    /* len 3, 7 bytes */

    struct BadMsg {
        const uint8_t *bytes;
        size_t len;
        DecodeError want;
    };
    const BadMsg bad[] = {
        {b_short, sizeof(b_short), DecodeError::Short},
        {b_version, sizeof(b_version), DecodeError::Version},
        {b_type, sizeof(b_type), DecodeError::Type},
        {b_oversize, sizeof(b_oversize), DecodeError::Oversize},
        {b_length, sizeof(b_length), DecodeError::Length},
    };
    for (const BadMsg &c : bad) {
        MessageView mv;
        Message m{};
        const DecodeError ev = decode_message_view(c.bytes, c.len, mv);
        const DecodeError ec = decode_message(c.bytes, c.len, m);
        TEST_ASSERT_EQUAL((int)c.want, (int)ev);
        TEST_ASSERT_EQUAL((int)ev, (int)ec);
    }
}

static void test_encode_message_into_matches(void)
{
    static const size_t sizes[] = {0, 1, 500, MAX_PAYLOAD};
    ByteBuf b;
    size_t cap = 0;
    bool first = true;
    for (size_t n : sizes) {
        std::vector<uint8_t> p(n);
        for (size_t i = 0; i < n; ++i) {
            p[i] = static_cast<uint8_t>(i * 7 + 3);
        }
        const uint8_t *src = p.empty() ? nullptr : p.data();

        TEST_ASSERT_TRUE(encode_message_into(MsgType::Data, 9, src, n, b));

        std::string ref;
        TEST_ASSERT_TRUE(encode_message(MsgType::Data, 9, src, n, ref));
        TEST_ASSERT_EQUAL_UINT((unsigned)ref.size(), (unsigned)b.size());
        TEST_ASSERT_EQUAL_INT(0, std::memcmp(b.data(), ref.data(), ref.size()));

        if (first) {
            cap = b.capacity();
            TEST_ASSERT_EQUAL_UINT((unsigned)MAX_MESSAGE, (unsigned)cap);
            first = false;
        } else {
            TEST_ASSERT_EQUAL_UINT((unsigned)cap, (unsigned)b.capacity());
        }
    }

    TEST_ASSERT_FALSE(encode_message_into(MsgType::Data, 9, nullptr, MAX_PAYLOAD + 1, b));
    TEST_ASSERT_EQUAL_UINT(0, (unsigned)b.size());
}

static void test_encode_data_prepare(void)
{
    ByteBuf b;
    uint8_t *p = encode_data_prepare(0x01020304u, 10, b);
    TEST_ASSERT_NOT_NULL(p);
    TEST_ASSERT_TRUE(p == b.data() + 4);
    TEST_ASSERT_EQUAL_UINT(14, (unsigned)b.size());
    for (size_t i = 0; i < 10; ++i) {
        p[i] = static_cast<uint8_t>(i);
    }

    std::string ref;
    TEST_ASSERT_TRUE(encode_data(0x01020304u, p, 10, ref));
    TEST_ASSERT_EQUAL_INT(0, std::memcmp(b.data(), ref.data(), 14));

    TEST_ASSERT_NOT_NULL(encode_data_prepare(0, MAX_PAYLOAD - 4, b));
    TEST_ASSERT_EQUAL_UINT((unsigned)MAX_PAYLOAD, (unsigned)b.size());

    const size_t before = b.size();
    TEST_ASSERT_TRUE(encode_data_prepare(0, MAX_PAYLOAD - 3, b) == nullptr);
    TEST_ASSERT_EQUAL_UINT((unsigned)before, (unsigned)b.size());
}

static void test_segmenter_heap_path_roundtrip(void)
{
    static const size_t packet_sizes[] = {20, 244, 300, 600};
    std::string msg(1000, '\0');
    for (size_t i = 0; i < msg.size(); ++i) {
        msg[i] = static_cast<char>(i * 13 + 1);
    }

    for (size_t packet_size : packet_sizes) {
        Segmenter s;
        std::vector<std::string> packets;
        const bool ok = s.send(
            reinterpret_cast<const uint8_t *>(msg.data()), msg.size(), packet_size,
            [&](const uint8_t *pkt, size_t len) {
                packets.push_back(std::string(reinterpret_cast<const char *>(pkt), len));
                return true;
            });
        TEST_ASSERT_TRUE(ok);
        TEST_ASSERT_EQUAL_UINT((unsigned)packets_per_message(msg.size(), packet_size),
                               (unsigned)packets.size());
        TEST_ASSERT_FALSE(packets.empty());
        for (const std::string &pkt : packets) {
            TEST_ASSERT_TRUE(pkt.size() <= packet_size);
        }
        TEST_ASSERT_EQUAL_UINT8(FLAG_START,
                                static_cast<uint8_t>(packets.front()[0]) & FLAG_START);
        TEST_ASSERT_EQUAL_UINT8(FLAG_END,
                                static_cast<uint8_t>(packets.back()[0]) & FLAG_END);

        std::string got;
        int messages = 0;
        int resets = 0;
        Reassembler r(
            [&](const uint8_t *m, size_t n) {
                got.assign(reinterpret_cast<const char *>(m), n);
                ++messages;
            },
            [&](ResetReason) { ++resets; });
        for (const std::string &pkt : packets) {
            r.feed(reinterpret_cast<const uint8_t *>(pkt.data()), pkt.size());
        }
        TEST_ASSERT_EQUAL_INT(1, messages);
        TEST_ASSERT_EQUAL_INT(0, resets);
        TEST_ASSERT_EQUAL_UINT((unsigned)msg.size(), (unsigned)got.size());
        TEST_ASSERT_EQUAL_INT(0, std::memcmp(got.data(), msg.data(), msg.size()));
    }
}

int main(int /*argc*/, char ** /*argv*/)
{
    UNITY_BEGIN();
    RUN_TEST(test_message_valid_roundtrip);
    RUN_TEST(test_message_malformed_reasons);
    RUN_TEST(test_segment_packets);
    RUN_TEST(test_segment_reassembles);
    RUN_TEST(test_reassemble_events);
    RUN_TEST(test_bulk_data_roundtrip);
    RUN_TEST(test_bulk_ack_roundtrip);
    RUN_TEST(test_bulk_bad_rejected);
    RUN_TEST(test_crc32_vectors);
    RUN_TEST(test_segmenter_send_rejects_bad_args);
    RUN_TEST(test_segmenter_send_sink_abort);
    RUN_TEST(test_rx_window);
    RUN_TEST(test_packet_size_for_mtu);
    RUN_TEST(test_next_conn_band);
    RUN_TEST(test_min_wait_ms);
    RUN_TEST(test_decode_view_matches_copy);
    RUN_TEST(test_encode_message_into_matches);
    RUN_TEST(test_encode_data_prepare);
    RUN_TEST(test_segmenter_heap_path_roundtrip);
    return UNITY_END();
}
